window.jspdf = window.jspdf || {};
window.jspdf.jsPDF = window.jspdf.jsPDF || {};
var fontRegular = '';
var fontBold = '';
window.jspdf.jsPDF.API.events.push(['addFonts', function() {
  this.addFileToVFS('Outfit-Regular.ttf', fontRegular);
  this.addFileToVFS('Outfit-Bold.ttf', fontBold);
  this.addFont('Outfit-Regular.ttf', 'Outfit', 'normal');
  this.addFont('Outfit-Bold.ttf', 'Outfit', 'bold');
}]);
